$string['settings:embed_apibaseurl'] = 'Embedding API Base URL';
$string['settings:embed_apibaseurl_desc'] = 'Base URL for the embedding API. Leave blank for OpenAI default. For Ollama: http://localhost:11434/api';
$string['settings:embed_apikey'] = 'Embedding API Key';
$string['settings:embed_apikey_desc'] = 'API key for the embedding provider. Can be different from the chat API key. Not required for Ollama.';
$string['settings:embed_dimensions'] = 'Embedding Dimensions';
$string['settings:embed_dimensions_desc'] = 'Breedte van de embeddingvector, die een breedte moet zijn die het model daadwerkelijk aanbiedt. OpenAI text-embedding-3-small: 1536. nomic-embed-text: 768. Voyage-modellen accepteren 256, 512, 1024 en 2048 (de eigen 1024 wordt uit het verzoek weggelaten); een ongeldige breedte wordt weggelaten in plaats van verzonden, dus u zou stilzwijgend de eigen breedte krijgen in plaats van de gevraagde. voyage-4-large op 2048 is de gemeten configuratie — +14,0 procentpunt recall op realistische queries, onder $4 per maand — en het invoeren ervan vereist een VOLLEDIGE HERINDEXERING, omdat de retriever weigert een query te scoren tegen chunks uit een andere embedding-ruimte. Gebruik de embedding-modelmigratie op de RAG-indexpagina in plaats van eerst deze waarde te wijzigen.';
$string['settings:embed_model'] = 'Embedding Model';
$string['settings:embed_model_desc'] = 'Model to use for generating embeddings. OpenAI default: text-embedding-3-small. Ollama example: nomic-embed-text.';
