// Cross-course mastery rollup (v5.7.0).
$string['pedagogy:crossmastery'] = 'Vakoverstijgende beheersingsoverzicht standaard ingeschakeld';
$string['pedagogy:crossmastery_desc'] = 'Indien ingeschakeld herkent [[tutorshort]] wanneer een cursist een doelstelling al in een andere cursus heeft beheerst (gematcht op competentiereferentie of titel) en erkent die eerder verworven competentie in plaats van die opnieuw te oefenen. Vereist beheersingsregistratie; cursussen zonder doelstellingen vallen netjes terug. Alleen adviserend: het wijzigt nooit de opgeslagen beheersingsscore van een cursist in welke cursus dan ook.';
$string['pedagogy:mastery_starter'] = 'Beheersingsbewuste gespreksstarter standaard ingeschakeld';
$string['pedagogy:mastery_starter_desc'] = 'Indien ingeschakeld wordt de gespreksstarter "Waar moet ik me op richten?" gepersonaliseerd om de zwakste doelstelling van de cursist te benoemen (en eventuele competenties die elders al beheerst zijn). Vereist beheersingsregistratie; valt terug op de algemene starter wanneer er nog geen beheersingsgegevens zijn.';
$string['task:rebuild_objective_links'] = 'Vakoverstijgende doelstellingskoppelingen voor beheersingsoverzicht opnieuw opbouwen (v5.7.0)';
$string['mastery_starter:practice_label'] = 'Oefenen: {$a}';
$string['objectives:rebuild_links_heading'] = 'Vakoverstijgende beheersingskoppelingen';
$string['objectives:rebuild_links_help'] = '[[tutorshort]] koppelt doelstellingen die overeenkomen tussen cursussen (op competentiereferentie of titel), zodat een cursist die een onderwerp elders heeft beheerst dit niet opnieuw hoeft te oefenen. De koppelingen worden elke nacht automatisch opnieuw opgebouwd; gebruik deze knop om ze nu opnieuw op te bouwen na het bewerken van doelstellingen.';
$string['objectives:rebuild_links_button'] = 'Koppelingen nu opnieuw opbouwen';
$string['objectives:rebuild_links_done'] = 'Vakoverstijgende beheersingskoppelingen opnieuw opgebouwd: {$a->total} in totaal ({$a->ref} op referentie, {$a->exact} exacte titel, {$a->fuzzy} benaderende titel).';

// Forward learning-path awareness (v5.8.0).
$string['pedagogy:program_path'] = 'Bewustzijn van het toekomstige leerpad standaard ingeschakeld';
$string['pedagogy:program_path_desc'] = 'Wanneer ingeschakeld, kan [[tutorshort]] een lerende vertellen waar de huidige cursus naartoe leidt binnen hun programma (diploma of certificaat) en hoe de concepten van vandaag aansluiten op latere cursussen. Leest de Moodle Programs-plug-in (Degrees en Learn) en benoemt alleen een specifieke volgende cursus wanneer het programma een vereiste of verplichte volgorde definieert; anders geeft het de positie van de lerende in het pad aan. Uitsluitend adviserend — het wijzigt nooit de inschrijving of de beheersing en gebruikt altijd alleen de programmatoewijzing van de lerende zelf. Doet stilzwijgend niets wanneer er geen programma van toepassing is.';

// Learning path map + next-course nudge (v5.9.0).
$string['pedagogy:learning_path'] = 'Leertrajectkaart en stimulans naar de volgende cursus standaard ingeschakeld';
$string['pedagogy:learning_path_desc'] = 'Wanneer ingeschakeld, voegt [[tutorshort]] een visueel leertrajectpaneel toe (een knop "mijn traject" in de widgetkop) dat het programma van de leerling toont als een reeks cursussen, elk uitvouwbaar naar de doelstellingen en de beheersing van de leerling. Wanneer de leerling de norm voor de huidige cursus heeft gehaald (afronding of een hoog aandeel beheerste doelstellingen), toont [[tutorshort]] ook een vriendelijke banner "klaar voor de volgende cursus" en vermeldt dit in het gesprek. Alleen adviserend; gebruikt de eigen programmatoewijzing van de leerling; doet stilletjes niets wanneer er geen programma van toepassing is.';
$string['settings:learning_path_mastery_threshold'] = 'Drempel voor gereedheid leertraject (%)';
$string['settings:learning_path_mastery_threshold_desc'] = 'Percentage van de gevolgde doelstellingen van een cursus dat een leerling moet beheersen voordat de leertrajectstimulans hen als klaar voor de volgende cursus beschouwt. Moodle-cursusafronding is de andere trigger; wat het eerst gebeurt, activeert de stimulans. Standaard 80.';
$string['pathpanel_title'] = 'Mijn leertraject';
$string['pathpanel_open'] = 'Mijn leertraject';
$string['pathpanel_empty'] = 'Er is nog geen programmatraject beschikbaar voor deze cursus.';
