$string['privacynotice:retention'] = 'Hoe lang [[tutorshort]] uw informatie bewaart';
$string['privacynotice:retention_item1'] = 'Uw gesprekken worden bewaard totdat u ze verwijdert of totdat de bewaartermijn voor gesprekken van de site (standaard twee jaar inactiviteit) ze automatisch verwijdert. Alleen de 10 meest recente wisselingen worden ooit naar het AI-model gestuurd.';
$string['privacynotice:retention_item2'] = 'Beoordelingen, studieplannen en herinneringen worden bewaard totdat u ze verwijdert.';
