$string['settings:bench_judge_provider_desc'] = 'Provider voor het model dat de antwoorden beoordeelt. Houd hem buiten de deelnemerspool: een model mag zichzelf niet beoordelen.';
$string['settings:bench_min_quality_n'] = 'Vergelijkbaarheidsdrempel (beoordeelde items)';
$string['settings:bench_min_quality_n_desc'] = 'Het kleinste aantal beoordeelde items dat een opgeslagen run mag hebben en toch met een andere run vergeleken mag worden. Runs onder de drempel worden bewaard en weergegeven, gelabeld als alleen ter referentie, zodat een smoke-run met drie prompts nooit boven een resultaat met vijftig prompts kan eindigen. Laat op 0 staan om de ingebouwde standaard te gebruiken; een drempel van 0 zou de beveiliging tenietdoen.';
$string['settings:embed_input_type_asymmetric'] = 'Asymmetrisch zoekopdracht/document (aanbevolen)';
$string['settings:embed_input_type_mode'] = 'Embedding-invoertype';
$string['settings:embed_input_type_mode_desc'] = 'Alleen voor Voyage-embeddings. Voyage projecteert tekst anders, afhankelijk van of het een zoekopdracht of een document is. "Asymmetrisch" stuurt input_type=query bij het ophalen en input_type=document bij het indexeren. Dat is wat de leverancier bedoelt en wat op dit corpus het beste meet: de documentprojectie aan de zoekkant kostte 30,8 procentpunt recall en verloor in elke lengtecategorie van zoekopdrachten (2026-08-21, voyage-3.5, productievormige set). "Gedeelde ruimte" stuurt input_type=document aan beide kanten; het haalt meetbaar slechter op en bestaat alleen als migratieverzekering, omdat één projectie het mogelijk maakt het zoekmodel te wijzigen zonder het corpus opnieuw te embedden. Kies asymmetrisch, tenzij u midden in een migratie zit. Dit wijzigen vereist geen herindexering: alleen de projectie aan de zoekkant verandert. Dit is NIET asymmetrische modelkoppeling (indexeren met een groter Voyage-model dan waarmee u zoekt) – dat is de andere techniek die op dit corpus twee keer niet reproduceerbaar was, en die wordt bepaald door de instelling voor het zoekmodel, niet door deze.';
$string['settings:embed_input_type_shared'] = 'Gedeelde ruimte (migratieverzekering; haalt slechter op)';
$string['settings:embed_migration_heading'] = 'Migratie van embedding-model';
$string['settings:embed_migration_heading_desc'] = 'Het wijzigen van het embedding-model of van de breedte ervan maakt elke opgeslagen vector ongeldig: de retriever weigert een query te scoren tegen chunks uit een andere embedding-ruimte, dus een cursus vindt niets in plaats van slecht te vinden. Deze instellingen beschrijven het model waar u NAARTOE gaat. Cursussen worden daarna één voor één opnieuw geëmbed vanaf de RAG-indexpagina, waarbij de nieuwe vectoren naast de oude worden geschreven, en de actieve instellingen hierboven blijven de opvraging verzorgen totdat u ze zelf wijzigt.';
$string['settings:embed_migration_provider_inherit'] = 'Gebruik de hierboven geconfigureerde provider';
$string['settings:embed_migration_target_apikey'] = 'API-sleutel van de doelprovider';
$string['settings:embed_migration_target_apikey_desc'] = 'Alleen nodig wanneer de doelprovider verschilt van de hierboven geconfigureerde. Leeg betekent dat de bestaande embedding-sleutel wordt gebruikt.';
$string['settings:embed_migration_target_dimensions'] = 'Doel-embeddingbreedte';
$string['settings:embed_migration_target_dimensions_desc'] = 'Vectorbreedte die tijdens de migratie wordt gevraagd. 0 betekent de eigen breedte van het model. Voyage accepteert 256, 512, 1024 en 2048; een breedte die het model niet aanbiedt, wordt uit het verzoek weggelaten in plaats van verzonden, wat u stilzwijgend de eigen breedte zou geven in plaats van de gevraagde.';
$string['settings:embed_migration_target_model'] = 'Doel-embeddingmodel';
$string['settings:embed_migration_target_model_desc'] = 'Modelnaam om tijdens de migratie mee te embedden, bijvoorbeeld <code>voyage-4-large</code>. Leeg betekent dat er geen migratie is geconfigureerd en dat de RAG-indexpagina er geen aanbiedt.';
$string['settings:embed_migration_target_provider'] = 'Doel-embeddingprovider';
$string['settings:embed_migration_target_provider_desc'] = 'Laat leeg om te migreren binnen de provider die hierboven al is geconfigureerd.';
$string['settings:rerank_min_query_chars'] = 'Rerank: minimale querylengte';
$string['settings:rerank_min_query_chars_desc'] = 'Sla de re-ranker over voor queries van dit aantal tekens of korter. Korte queries zijn trefwoordachtig en de re-ranker voegt bij twee of drie woorden bijna niets toe aan cosinus-gelijkenis. Gemeten op de RAG-fixtureset: begrenzen bij 50 leverde 67,7% recall tegen 67,2% voor altijd-aan, tegen ongeveer een derde van de kosten. Zet op 0 om elke query te reranken. Overgeslagen reranks worden in het berichtenlog vastgelegd als "[Rerank skipped: short_query]" zodat u kunt controleren of de drempel werkt.';
$string['settings:spend_export_key'] = 'Sleutel voor uitgaven-export';
$string['settings:spend_export_key_desc'] = 'Bearer-sleutel voor het maandelijkse eindpunt voor de AI-uitgaven-export op <code>/local/ai_course_assistant/spend_export.php</code>, dat het uitgavendashboard één keer per maand ophaalt. Laat leeg om het eindpunt uit te schakelen — het geeft dan op elk verzoek 404 terug. De sleutel wordt UITSLUITEND geaccepteerd in een <code>Authorization: Bearer</code>-header, nooit in de URL. Genereer een lange willekeurige waarde; wie hem heeft, kan de AI-uitgaven van de hele site lezen. Elke geslaagde export wordt vastgelegd in het auditlog van de plugin.';
$string['task:migrate_course_embeddings'] = 'Eén cursus naar een nieuw embedding-model migreren';
$string['task:model_price_drift_check'] = 'Controle op prijsdrift van modellen';
$string['task:run_model_benchmark'] = 'Een model benchmarken';
